export const COSTOS_CALC_MONTHS = ['ENERO','FEBRERO','MARZO','ABRIL','MAYO','JUNIO','JULIO','AGOSTO','SEPTIEMBRE','OCTUBRE','NOVIEMBRE','DICIEMBRE'];


// Auto-fill de las filas resumen MOD / GV / GF (333-343) que en el seed solo
// traen ENERO. La formula propaga a todos los meses asi:
//   333 (MOD REAL)  <- r=217 (MANO DE OBRA DIRECTA total post-prorrateo)
//   337 (GTOS V)    <- r=218 (GASTOS VARIABLES total)
//   341 (GTOS F)    <- r=219 (GASTOS FIJOS total)
//   334/338/342 (ABSORCION MOD/GV/GF) <- r=328 (ABSORCIONES POR PRODUCCION) prorrateado
//                     usando las proporciones de ENERO (unica fuente disponible).
//   335/339/343 (VARIACION MOD/GV/GF) <- Real menos Absorcion
(() => {
  const find = (rNum) => COSTOS_CALC_ROWS.find((row) => row.r === rNum);
  const rMod = find(217), rGv = find(218), rGf = find(219), rAbsTot = find(328);
  const r333 = find(333), r334 = find(334), r335 = find(335);
  const r337 = find(337), r338 = find(338), r339 = find(339);
  const r341 = find(341), r342 = find(342), r343 = find(343);
  if (!rMod || !rGv || !rGf || !rAbsTot) return;
  if (!r333 || !r334 || !r335 || !r337 || !r338 || !r339 || !r341 || !r342 || !r343) return;

  const absTotEne = rAbsTot.months[0] || 0;
  const ratioMod = absTotEne > 0 ? (r334.months[0] || 0) / absTotEne : 0;
  const ratioGv  = absTotEne > 0 ? (r338.months[0] || 0) / absTotEne : 0;
  const ratioGf  = absTotEne > 0 ? (r342.months[0] || 0) / absTotEne : 0;

  for (let i = 0; i < 12; i++) {
    if (r333.months[i] == null) r333.months[i] = rMod.months[i] ?? 0;
    if (r337.months[i] == null) r337.months[i] = rGv.months[i]  ?? 0;
    if (r341.months[i] == null) r341.months[i] = rGf.months[i]  ?? 0;
    const absTot = rAbsTot.months[i] ?? 0;
    if (r334.months[i] == null) r334.months[i] = absTot * ratioMod;
    if (r338.months[i] == null) r338.months[i] = absTot * ratioGv;
    if (r342.months[i] == null) r342.months[i] = absTot * ratioGf;
    if (r335.months[i] == null) r335.months[i] = r333.months[i] - r334.months[i];
    if (r339.months[i] == null) r339.months[i] = r337.months[i] - r338.months[i];
    if (r343.months[i] == null) r343.months[i] = r341.months[i] - r342.months[i];
  }

  const sumMonths = (row) => row.months.reduce((s, n) => s + (n ?? 0), 0);
  [r333, r334, r335, r337, r338, r339, r341, r342, r343].forEach((row) => {
    row.total = sumMonths(row);
  });
})();
